import SwiftUI

public struct ManicatRidgelineSeries: Identifiable {
    public let id: String
    public let label: String
    public let values: [Double]

    public init(id: String, label: String, values: [Double]) {
        self.id = id
        self.label = label
        self.values = values
    }
}

/// Mirrors ridgeline.tsx / ridgeline.rn.tsx / ridgeline.vue: stacked, overlapping area charts that share one scale.
public struct ManicatRidgeline: View {
    public struct Styles {
        public var readout: ManicatStyle = { $0 }
        public var rowLabel: ManicatStyle = { $0 }
        public init() {}
    }

    @Environment(\.manicat) private var tokens
    @State private var active: String?

    private let series: [ManicatRidgelineSeries]
    private let label: String
    private let unit: String
    private let formatValue: (Double) -> String
    private let overlap: Double
    private let rowHeight: CGFloat
    private let tint: Bool
    private let emptyLabel: String
    private let styles: Styles

    public init(series: [ManicatRidgelineSeries], label: String, unit: String = "", formatValue: @escaping (Double) -> String = { $0.formatted() }, overlap: Double = 0.6, rowHeight: CGFloat = 56, tint: Bool = false, emptyLabel: String = "No data yet", styles: Styles = Styles()) {
        self.series = series
        self.label = label
        self.unit = unit
        self.formatValue = formatValue
        self.overlap = overlap
        self.rowHeight = rowHeight
        self.tint = tint
        self.emptyLabel = emptyLabel
        self.styles = styles
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: ManicatMetrics.space.s2) {
            Text(label).font(.system(size: ManicatMetrics.textSm, weight: .medium)).foregroundStyle(tokens.foreground)
            if series.isEmpty {
                Text(emptyLabel).font(.system(size: ManicatMetrics.textSm)).foregroundStyle(tokens.textMuted)
            } else {
                Text(active.flatMap { id in series.first { $0.id == id } }.map { "\($0.label): average \(formatValue(mean($0).rounded()))\(unit.isEmpty ? "" : " \(unit)")" } ?? " ")
                    .font(.system(size: ManicatMetrics.textXs))
                    .foregroundStyle(tokens.textSecondary)
                    .frame(minHeight: 16, alignment: .leading)
                    .manicatStyle(styles.readout)
                chart
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private var chart: some View {
        let step = rowHeight * CGFloat(1 - overlap)
        let height = step * CGFloat(series.count - 1) + rowHeight + 4
        let top = max(1, series.flatMap(\.values).max() ?? 1)

        return GeometryReader { proxy in
            ZStack(alignment: .topLeading) {
                ForEach(Array(series.enumerated()), id: \.element.id) { index, entry in
                    let base = CGFloat(index) * step + rowHeight
                    let x = ManicatChart.linearScale(domain: (0, Double(max(1, entry.values.count - 1))), range: (0, Double(proxy.size.width)))
                    let y = ManicatChart.linearScale(domain: (0, top), range: (Double(base), Double(base - rowHeight)))
                    let points = entry.values.enumerated().map { CGPoint(x: x(Double($0.offset)), y: y($0.element)) }
                    let color = tint ? tokens.series[index % 4] : tokens.series[0]
                    ZStack(alignment: .topLeading) {
                        ManicatChart.areaPath(points, baseline: base).fill(color.opacity(0.35))
                        ManicatChart.linePath(points).stroke(color, lineWidth: 1.5)
                        Text(entry.label).font(.system(size: 11)).foregroundStyle(tokens.foreground).manicatStyle(styles.rowLabel).offset(y: base - 18)
                    }
                    .opacity(active != nil && active != entry.id ? 0.35 : 1)
                    .onTapGesture { active = active == entry.id ? nil : entry.id }
                    .accessibilityLabel("\(entry.label), average \(formatValue(mean(entry).rounded()))")
                }
            }
        }
        .frame(height: height)
    }

    private func mean(_ entry: ManicatRidgelineSeries) -> Double { entry.values.reduce(0, +) / Double(max(1, entry.values.count)) }
}

import SwiftUI

/// The Manicat UI design tokens as SwiftUI values. Same names and meaning as registry/foundation.css and lib/rn-tokens.ts.
/// `scripts/check-parity.mjs` compares every colour below with rn-tokens.ts, so the three never drift.
public struct ManicatTokens {
    public let background, surface, surfaceMuted, foreground, textSecondary, textMuted, border, borderStrong: Color
    public let accent, accentStrong, accentSubtle, success, warning, danger: Color
    public let controlOn, controlTrack, controlThumb, controlThumbOn: Color
    /// Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4.
    public let series: [Color]

    public static let light = ManicatTokens(
        background: Color(hex: "#ffffff"), surface: Color(hex: "#ffffff"), surfaceMuted: Color(hex: "#f6f6f6"),
        foreground: Color(hex: "#1b1b1b"), textSecondary: Color(hex: "#6e6e6e"), textMuted: Color(hex: "#8f8f8f"),
        border: Color(hex: "#ebebeb"), borderStrong: Color(hex: "#c9c9c9"),
        accent: Color(hex: "#4a4a4a"), accentStrong: Color(hex: "#303030"), accentSubtle: Color(hex: "#4a4a4a", opacity: 0.1),
        success: Color(hex: "#1f8a4c"), warning: Color(hex: "#b8741a"), danger: Color(hex: "#d03b3b"),
        controlOn: Color(hex: "#2c2c2c"), controlTrack: Color(hex: "#e2e2e2"), controlThumb: Color(hex: "#ffffff"), controlThumbOn: Color(hex: "#ffffff"),
        series: [Color(hex: "#1f7dcf"), Color(hex: "#7128a5"), Color(hex: "#e58f00"), Color(hex: "#009e84")]
    )

    public static let dark = ManicatTokens(
        background: Color(hex: "#2b2b2b"), surface: Color(hex: "#303030"), surfaceMuted: Color(hex: "#3c3c3c"),
        foreground: Color(hex: "#f1f1f1"), textSecondary: Color(hex: "#c4c4c4"), textMuted: Color(hex: "#a0a0a0"),
        border: Color(hex: "#454545"), borderStrong: Color(hex: "#5c5c5c"),
        accent: Color(hex: "#cfcfcf"), accentStrong: Color(hex: "#e6e6e6"), accentSubtle: Color(hex: "#cfcfcf", opacity: 0.13),
        success: Color(hex: "#5fd48a"), warning: Color(hex: "#f0b95c"), danger: Color(hex: "#ff8a80"),
        controlOn: Color(hex: "#ececec"), controlTrack: Color(hex: "#515151"), controlThumb: Color(hex: "#f4f4f4"), controlThumbOn: Color(hex: "#2b2b2b"),
        series: [Color(hex: "#55adff"), Color(hex: "#9c37be"), Color(hex: "#e66e00"), Color(hex: "#00a861")]
    )
}

/// Shape and rhythm shared by every component, in points.
public enum ManicatMetrics {
    public static let radiusControl: CGFloat = 18
    public static let radiusPill: CGFloat = 9999
    public static let controlHeight: (sm: CGFloat, md: CGFloat, lg: CGFloat) = (36, 44, 50)
    public static let space: (s1: CGFloat, s2: CGFloat, s3: CGFloat, s4: CGFloat, s5: CGFloat) = (4, 8, 12, 16, 20)
    public static let textXs: CGFloat = 12
    public static let textSm: CGFloat = 14
    public static let textLg: CGFloat = 18
}

/// Restyles one named part of a component. The counterpart of an entry of `classNames` on the web and of `styles` on React Native:
/// every component has a `Styles` struct with one of these per part, and applies it to that part.
public typealias ManicatStyle = (AnyView) -> AnyView

public extension View {
    /// Applies a `ManicatStyle` to this view.
    func manicatStyle(_ style: ManicatStyle) -> some View { style(AnyView(self)) }
}

/// Lays children out in rows that wrap, like flex-wrap on the web. Used by chips, tags, breadcrumbs and anything else that flows.
public struct ManicatFlowLayout: Layout {
    public var spacing: CGFloat
    public var lineSpacing: CGFloat

    public init(spacing: CGFloat = 8, lineSpacing: CGFloat = 8) {
        self.spacing = spacing
        self.lineSpacing = lineSpacing
    }

    public func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        arrange(width: proposal.width ?? .infinity, subviews: subviews).size
    }

    public func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let result = arrange(width: bounds.width, subviews: subviews)
        for (index, origin) in result.origins.enumerated() {
            subviews[index].place(at: CGPoint(x: bounds.minX + origin.x, y: bounds.minY + origin.y), proposal: .unspecified)
        }
    }

    private func arrange(width: CGFloat, subviews: Subviews) -> (size: CGSize, origins: [CGPoint]) {
        var origins: [CGPoint] = []
        var x: CGFloat = 0, y: CGFloat = 0, rowHeight: CGFloat = 0, widest: CGFloat = 0
        for subview in subviews {
            let size = subview.sizeThatFits(.unspecified)
            if x > 0, x + size.width > width {
                x = 0
                y += rowHeight + lineSpacing
                rowHeight = 0
            }
            origins.append(CGPoint(x: x, y: y))
            x += size.width + spacing
            rowHeight = max(rowHeight, size.height)
            widest = max(widest, x - spacing)
        }
        return (CGSize(width: widest, height: y + rowHeight), origins)
    }
}

private struct ManicatTokensKey: EnvironmentKey {
    static let defaultValue = ManicatTokens.light
}

public extension EnvironmentValues {
    /// The tokens for the current colour scheme. Read them with `@Environment(\.manicat)`.
    var manicat: ManicatTokens {
        get { colorScheme == .dark ? .dark : self[ManicatTokensKey.self] }
        set { self[ManicatTokensKey.self] = newValue }
    }
}

public extension Color {
    init(hex: String, opacity: Double = 1) {
        let digits = hex.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
        var value: UInt64 = 0
        Scanner(string: digits).scanHexInt64(&value)
        self.init(.sRGB, red: Double((value >> 16) & 0xff) / 255, green: Double((value >> 8) & 0xff) / 255, blue: Double(value & 0xff) / 255, opacity: opacity)
    }
}

import SwiftUI

/// Geometry shared by the chart ports: the Swift counterpart of lib/chart.ts. Pure functions that turn data into scales, ticks
/// and SwiftUI `Path`s, and leave drawing to each port.
public enum ManicatChart {
    public enum Curve { case smooth, linear }

    /// Maps a value from a domain to a range, like d3's linear scale.
    public struct Scale {
        public let domain: (Double, Double)
        public let range: (Double, Double)

        public func callAsFunction(_ value: Double) -> Double {
            domain.1 == domain.0 ? (range.0 + range.1) / 2 : range.0 + ((value - domain.0) / (domain.1 - domain.0)) * (range.1 - range.0)
        }
    }

    public static func linearScale(domain: (Double, Double), range: (Double, Double)) -> Scale {
        Scale(domain: domain, range: range)
    }

    /// A tidy upper bound for a data maximum: 1, 2, 2.5, 5 or 10 times a power of ten.
    public static func niceMax(_ max: Double) -> Double {
        if max <= 0 { return 1 }
        let power = pow(10, floor(log10(max)))
        let fraction = max / power
        let step: Double = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10
        return step * power
    }

    /// `count + 1` evenly spaced tick values from 0 to a nice maximum.
    public static func ticks(_ max: Double, count: Int = 4) -> [Double] {
        let top = niceMax(max)
        return (0...count).map { top / Double(count) * Double($0) }
    }

    /// 1,200 reads 1.2K, like the web's compact notation.
    public static func compact(_ value: Double) -> String {
        let size = abs(value)
        let (scale, unit): (Double, String) = size >= 1e9 ? (1e9, "B") : size >= 1e6 ? (1e6, "M") : size >= 1e3 ? (1e3, "K") : (1, "")
        let scaled = (value / scale * 10).rounded() / 10
        return (scaled == scaled.rounded() ? String(Int(scaled)) : String(scaled)) + unit
    }

    /// A straight polyline, or a smooth curve through the points (Catmull-Rom converted to cubic Béziers).
    public static func linePath(_ points: [CGPoint], curve: Curve = .smooth) -> Path {
        var path = Path()
        guard let first = points.first else { return path }
        path.move(to: first)
        if points.count == 1 { return path }
        if curve == .linear {
            for point in points.dropFirst() { path.addLine(to: point) }
            return path
        }
        for index in 0..<(points.count - 1) {
            let p0 = index > 0 ? points[index - 1] : points[index]
            let p1 = points[index]
            let p2 = points[index + 1]
            let p3 = index + 2 < points.count ? points[index + 2] : p2
            let c1 = CGPoint(x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6)
            let c2 = CGPoint(x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6)
            path.addCurve(to: p2, control1: c1, control2: c2)
        }
        return path
    }

    /// The area between a line and the baseline `y0`.
    public static func areaPath(_ points: [CGPoint], baseline y0: CGFloat, curve: Curve = .smooth) -> Path {
        var path = linePath(points, curve: curve)
        guard let first = points.first, let last = points.last else { return path }
        path.addLine(to: CGPoint(x: last.x, y: y0))
        path.addLine(to: CGPoint(x: first.x, y: y0))
        path.closeSubpath()
        return path
    }

    /// A band between an upper and a lower line, for stacked areas.
    public static func bandPath(upper: [CGPoint], lower: [CGPoint], curve: Curve = .smooth) -> Path {
        var path = linePath(upper, curve: curve)
        let back = Array(lower.reversed())
        guard let start = back.first else { return path }
        path.addLine(to: start)
        path.addPath(linePath(back, curve: curve))
        path.closeSubpath()
        return path
    }

    /// A ring segment from `a0` to `a1` radians (0 is 12 o'clock, clockwise).
    public static func arcPath(center: CGPoint, outer: CGFloat, inner: CGFloat, from a0: Double, to a1: Double) -> Path {
        let sweep = min(a1 - a0, Double.pi * 2 - 0.0001)
        let end = a0 + sweep
        func point(_ radius: CGFloat, _ angle: Double) -> CGPoint {
            CGPoint(x: center.x + radius * CGFloat(sin(angle)), y: center.y - radius * CGFloat(cos(angle)))
        }
        // SwiftUI measures arcs from 3 o'clock, so the angles are shifted a quarter turn.
        let quarter = Angle.radians(-Double.pi / 2)
        var path = Path()
        path.move(to: point(outer, a0))
        path.addArc(center: center, radius: outer, startAngle: .radians(a0) + quarter, endAngle: .radians(end) + quarter, clockwise: false)
        path.addLine(to: point(inner, end))
        path.addArc(center: center, radius: inner, startAngle: .radians(end) + quarter, endAngle: .radians(a0) + quarter, clockwise: true)
        path.closeSubpath()
        return path
    }

    /// Squarified treemap: lays `values` out in `rect`, keeping cells close to square. Returns one rect per value, in input order.
    public static func squarify(_ values: [Double], in rect: CGRect) -> [CGRect] {
        let total = values.reduce(0, +)
        if total <= 0 { return values.map { _ in CGRect(x: rect.minX, y: rect.minY, width: 0, height: 0) } }
        var out = [CGRect](repeating: .zero, count: values.count)
        let order = values.enumerated().map { (index: $0.offset, value: $0.element) }.sorted { $0.value > $1.value }
        var free = rect
        var remaining = total
        var row: [(index: Int, value: Double)] = []

        func worst(_ items: [(index: Int, value: Double)], side: Double, scale: Double) -> Double {
            let scaled = items.map { $0.value * scale }
            let sum = scaled.reduce(0, +)
            let largest = scaled.max() ?? 0
            let smallest = scaled.min() ?? 0
            return max(side * side * largest / (sum * sum), sum * sum / (side * side * smallest))
        }

        func place(_ items: [(index: Int, value: Double)], scale: Double) {
            let sum = items.reduce(0) { $0 + $1.value * scale }
            let horizontal = free.width >= free.height
            let thickness = sum / Double(horizontal ? free.height : free.width)
            var offset = 0.0
            for item in items {
                let length = item.value * scale / thickness
                out[item.index] = horizontal
                    ? CGRect(x: free.minX, y: free.minY + offset, width: thickness, height: length)
                    : CGRect(x: free.minX + offset, y: free.minY, width: length, height: thickness)
                offset += length
            }
            free = horizontal
                ? CGRect(x: free.minX + thickness, y: free.minY, width: free.width - thickness, height: free.height)
                : CGRect(x: free.minX, y: free.minY + thickness, width: free.width, height: free.height - thickness)
            remaining -= items.reduce(0) { $0 + $1.value }
        }

        for item in order {
            let scale = Double(free.width * free.height) / remaining
            let side = Double(min(free.width, free.height))
            if row.isEmpty || worst(row + [item], side: side, scale: scale) <= worst(row, side: side, scale: scale) {
                row.append(item)
            } else {
                place(row, scale: scale)
                row = [item]
            }
        }
        if !row.isEmpty { place(row, scale: Double(free.width * free.height) / remaining) }
        return out
    }
}
